--
-- Name: v_invoice_balance; Type: VIEW; Schema: shop; Owner: -
--

CREATE VIEW shop.v_invoice_balance AS
 SELECT o.sales_order_id,
    o.invoice_no,
    o.order_date,
    o.due_date,
    o.customer_id,
    o.payment_method,
    o.status,
    t.total,
        CASE
            WHEN (o.payment_method = 'credit'::text) THEN COALESCE(p.paid, (0)::numeric)
            ELSE t.total
        END AS paid,
    (t.total -
        CASE
            WHEN (o.payment_method = 'credit'::text) THEN COALESCE(p.paid, (0)::numeric)
            ELSE t.total
        END) AS balance
   FROM ((shop.sales_orders o
     JOIN ( SELECT sales_order_lines.sales_order_id,
            sum(sales_order_lines.line_total) AS total
           FROM shop.sales_order_lines
          GROUP BY sales_order_lines.sales_order_id) t USING (sales_order_id))
     LEFT JOIN ( SELECT customer_payments.sales_order_id,
            sum(customer_payments.amount) AS paid
           FROM shop.customer_payments
          GROUP BY customer_payments.sales_order_id) p USING (sales_order_id))
  WHERE (o.status = 'completed'::text);


--
-- Name: v_stock_on_hand; Type: VIEW; Schema: shop; Owner: -
--

CREATE VIEW shop.v_stock_on_hand AS
 SELECT p.product_id,
    p.sku,
    p.product_name,
    p.unit,
    p.reorder_point,
    COALESCE(a.q, (0)::bigint) AS adjusted_qty,
    COALESCE(r.q, (0)::bigint) AS received_qty,
    COALESCE(s.q, (0)::bigint) AS sold_qty,
    ((COALESCE(a.q, (0)::bigint) + COALESCE(r.q, (0)::bigint)) - COALESCE(s.q, (0)::bigint)) AS stock_qty
   FROM (((shop.products p
     LEFT JOIN ( SELECT stock_adjustments.product_id,
            sum(stock_adjustments.quantity_change) AS q
           FROM shop.stock_adjustments
          GROUP BY stock_adjustments.product_id) a USING (product_id))
     LEFT JOIN ( SELECT l.product_id,
            sum(l.quantity) AS q
           FROM (shop.purchase_order_lines l
             JOIN shop.purchase_orders o USING (purchase_order_id))
          WHERE (o.status = 'received'::text)
          GROUP BY l.product_id) r USING (product_id))
     LEFT JOIN ( SELECT l.product_id,
            sum(l.quantity) AS q
           FROM (shop.sales_order_lines l
             JOIN shop.sales_orders o USING (sales_order_id))
          WHERE (o.status = 'completed'::text)
          GROUP BY l.product_id) s USING (product_id));


--
-- Name: v_data_checks; Type: VIEW; Schema: shop; Owner: -
--

CREATE VIEW shop.v_data_checks AS
 SELECT check_name,
    severity,
    rows_found,
    meaning
   FROM ( SELECT 'C01 บิลที่ไม่มีรายการสินค้า'::text AS check_name,
            'ต้องเป็น 0'::text AS severity,
            ( SELECT count(*) AS count
                   FROM shop.sales_orders o
                  WHERE (NOT (EXISTS ( SELECT 1
                           FROM shop.sales_order_lines l
                          WHERE (l.sales_order_id = o.sales_order_id))))) AS rows_found,
            'บิลที่มีหัวบิลแต่ไม่มีสินค้า'::text AS meaning
        UNION ALL
         SELECT 'C02 ใบสั่งซื้อที่ไม่มีรายการ'::text,
            'ต้องเป็น 0'::text,
            ( SELECT count(*) AS count
                   FROM shop.purchase_orders o
                  WHERE (NOT (EXISTS ( SELECT 1
                           FROM shop.purchase_order_lines l
                          WHERE (l.purchase_order_id = o.purchase_order_id))))) AS count,
            'PO ว่าง'::text
        UNION ALL
         SELECT 'C03 สินค้าที่สต็อกติดลบ'::text,
            'ต้องเป็น 0'::text,
            ( SELECT count(*) AS count
                   FROM shop.v_stock_on_hand
                  WHERE ((v_stock_on_hand.stock_qty < 0) AND (v_stock_on_hand.sku <> 'UNMAPPED'::text))) AS count,
            'ขายมากกว่าที่รับเข้า/ยกมา'::text
        UNION ALL
         SELECT 'C04 บิลเครดิตที่รับชำระเกินยอดบิล'::text,
            'ต้องเป็น 0'::text,
            ( SELECT count(*) AS count
                   FROM shop.v_invoice_balance
                  WHERE (v_invoice_balance.balance < '-0.005'::numeric)) AS count,
            'รับเงินเกินยอดบิล'::text
        UNION ALL
         SELECT 'C05 การรับชำระก่อนวันที่ขาย'::text,
            'ต้องเป็น 0'::text,
            ( SELECT count(*) AS count
                   FROM (shop.customer_payments p
                     JOIN shop.sales_orders o USING (sales_order_id))
                  WHERE (p.paid_date < o.order_date)) AS count,
            'วันที่รับเงินผิด'::text
        UNION ALL
         SELECT 'C06 บิลเครดิตของลูกค้าที่ไม่มีเครดิต'::text,
            'ต้องเป็น 0'::text,
            ( SELECT count(*) AS count
                   FROM (shop.sales_orders o
                     JOIN shop.customers c USING (customer_id))
                  WHERE ((o.payment_method = 'credit'::text) AND (c.credit_days = 0))) AS count,
            'ขายเชื่อให้คนที่ไม่มีเครดิต'::text
        UNION ALL
         SELECT 'C07 ขายเกินวงเงินเครดิต (ยอดค้างปัจจุบัน)'::text,
            'รายการที่ต้องให้ร้านยืนยัน'::text,
            ( SELECT count(*) AS count
                   FROM (( SELECT v_invoice_balance.customer_id,
                            sum(v_invoice_balance.balance) AS b
                           FROM shop.v_invoice_balance
                          WHERE (v_invoice_balance.payment_method = 'credit'::text)
                          GROUP BY v_invoice_balance.customer_id) x
                     JOIN shop.customers c USING (customer_id))
                  WHERE ((x.b > c.credit_limit) AND (c.credit_limit > (0)::numeric))) AS count,
            'ยอดค้างชำระมากกว่าวงเงิน'::text
        UNION ALL
         SELECT 'C08 ราคาขายต่ำกว่าทุน'::text,
            'รายการที่ต้องให้ร้านยืนยัน'::text,
            ( SELECT count(*) AS count
                   FROM ((shop.sales_order_lines l
                     JOIN shop.products p USING (product_id))
                     JOIN shop.sales_orders o USING (sales_order_id))
                  WHERE ((l.unit_price < p.cost_price) AND (p.sku <> 'UNMAPPED'::text) AND (o.status = 'completed'::text))) AS count,
            'อาจพิมพ์ราคาผิด'::text
        UNION ALL
         SELECT 'C09 รายการสินค้าที่ระบุไม่ได้ (UNMAPPED)'::text,
            'รายการที่ต้องให้ร้านยืนยัน'::text,
            ( SELECT count(*) AS count
                   FROM (shop.sales_order_lines l
                     JOIN shop.products p USING (product_id))
                  WHERE (p.sku = 'UNMAPPED'::text)) AS count,
            'ต้องให้ร้านบอกว่าเป็นสินค้าอะไร'::text
        UNION ALL
         SELECT 'C10 ใบสั่งซื้อที่วันที่รับของเป็นค่าประมาณ'::text,
            'รายการที่ต้องให้ร้านยืนยัน'::text,
            ( SELECT count(*) AS count
                   FROM shop.purchase_orders
                  WHERE purchase_orders.received_date_is_estimated) AS count,
            'ไม่มีวันที่รับของในไฟล์เดิม'::text
        UNION ALL
         SELECT 'C11 สต็อกในระบบไม่ตรงกับยอดนับจริง'::text,
            'รายการที่ต้องให้ร้านยืนยัน'::text,
            ( SELECT count(*) AS count
                   FROM (shop.stock_counts c
                     JOIN shop.v_stock_on_hand s USING (product_id))
                  WHERE (c.counted_qty <> s.stock_qty)) AS count,
            'ของหาย/นับผิด/บันทึกขายผิด'::text
        UNION ALL
         SELECT 'C12 สินค้าไม่เคลื่อนไหว 90 วัน แต่ยังมีสต็อก'::text,
            'ข้อมูลเพื่อตัดสินใจ'::text,
            ( SELECT count(*) AS count
                   FROM shop.v_stock_on_hand s
                  WHERE ((s.stock_qty > 0) AND (s.sku <> 'UNMAPPED'::text) AND (NOT (EXISTS ( SELECT 1
                           FROM (shop.sales_order_lines l
                             JOIN shop.sales_orders o USING (sales_order_id))
                          WHERE ((l.product_id = s.product_id) AND (o.status = 'completed'::text) AND (o.order_date > ('2026-10-31'::date - 90)))))))) AS count,
            'เงินจมในสต็อก'::text) t
  ORDER BY check_name;


--
-- Name: v_low_stock; Type: VIEW; Schema: shop; Owner: -
--

CREATE VIEW shop.v_low_stock AS
 SELECT sku,
    product_name,
    stock_qty,
    reorder_point
   FROM shop.v_stock_on_hand
  WHERE (stock_qty <= reorder_point)
  ORDER BY (stock_qty - reorder_point);


--
-- Name: v_sales_detail; Type: VIEW; Schema: shop; Owner: -
--

CREATE VIEW shop.v_sales_detail AS
 SELECT o.order_date,
    o.invoice_no,
    c.customer_code,
    c.customer_name,
    c.customer_type,
    o.payment_method,
    p.sku,
    p.product_name,
    pc.category_name,
    l.quantity,
    l.unit_price,
    l.discount,
    l.line_total,
    p.cost_price,
    ((l.quantity)::numeric * p.cost_price) AS cost_total,
    (l.line_total - ((l.quantity)::numeric * p.cost_price)) AS gross_profit
   FROM ((((shop.sales_order_lines l
     JOIN shop.sales_orders o USING (sales_order_id))
     JOIN shop.customers c USING (customer_id))
     JOIN shop.products p USING (product_id))
     JOIN shop.product_categories pc USING (category_id))
  WHERE (o.status = 'completed'::text);


--
-- Name: v_sales_monthly; Type: VIEW; Schema: shop; Owner: -
--

CREATE VIEW shop.v_sales_monthly AS
 SELECT (date_trunc('month'::text, (order_date)::timestamp with time zone))::date AS month,
    customer_type,
    count(DISTINCT invoice_no) AS invoices,
    sum(line_total) AS sales,
    sum(gross_profit) AS gross_profit,
    round((((100)::numeric * sum(gross_profit)) / NULLIF(sum(line_total), (0)::numeric)), 1) AS gross_margin_pct
   FROM shop.v_sales_detail
  GROUP BY ((date_trunc('month'::text, (order_date)::timestamp with time zone))::date), customer_type
  ORDER BY ((date_trunc('month'::text, (order_date)::timestamp with time zone))::date), customer_type;


